{
  "title": "Monthly rainfall summary",
  "body": "<div class="card">
  <figure>
    <ml-embed ref="@tool:3fa9c21:out"></ml-embed>
    <figcaption>Figure: Monthly rainfall during the year (mm)</figcaption>
  </figure>
  <div class="stats">
    <h2>Wettest months</h2>
    <ol id="wettest"></ol>
    <p class="total">Yearly total: <span id="total"></span> mm</p>
  </div>
</div>",
  "css": ".card {
  font-family: system-ui, -apple-system, sans-serif;
  max-width: 640px;
  margin: 0 auto;
  padding: 16px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
}
figure {
  margin: 0 0 16px;
}
ml-embed,
figure img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
}
figcaption {
  text-align: center;
  font-size: 0.9em;
  color: #475569;
  margin-top: 8px;
}
h2 {
  font-size: 1.1rem;
  margin: 0 0 8px;
}
ol {
  margin: 0 0 12px;
  padding-left: 20px;
}
li {
  margin: 2px 0;
}
.total {
  font-weight: 600;
}",
  "scripts": [
    "const csvText = (ml.dereference('@tool:7be01d4:out') || '').trim();
const lines = csvText.split('\n');
const data = lines.slice(1).map(line => {
  const parts = line.trim().split(',');
  return { month: parts[0].trim(), mm: Number(parts[1]) };
}).filter(row => row.month && !Number.isNaN(row.mm));
const wettest = [...data].sort((a, b) => b.mm - a.mm).slice(0, 3);
const total = data.reduce((sum, row) => sum + row.mm, 0);
const list = root.querySelector('#wettest');
const totalEl = root.querySelector('#total');
const items = wettest.map(row => {
  const li = root.create('li');
  li.textContent = row.month + ': ' + row.mm + ' mm';
  return li;
});
list.replaceChildren(...items);
totalEl.textContent = String(total);"
  ]
}
```
